function createUpdateBody(record, username) {
    let historyObject = [];
    let updatedActions = [];
    let status = "in_progress";

    try {
        if (typeof record.history === "string") {
            historyObject = JSON.parse(record.history);
        } else if (Array.isArray(record.history)) {
            historyObject = record.history;
        }
    } catch (e) {
        historyObject = [];
    }

    let newEvent = {
        "event": "Action status update: " + status,
        "comments": "Action status has been updated to:" + status,
        "timestamp": Math.floor(Date.now() / 1000),
        "user": username
    };

    historyObject.push(newEvent);

    const action = {
        action_id: record.actions_identifier,
        status: status,
        history: JSON.stringify(historyObject)
    };

    updatedActions.push(action);
    return updatedActions;
};

