function mergePatchesForAllOS(payload) {
  for (const osKey of Object.keys(payload)) {
    const osData = payload[osKey];

    if (!osData || !Array.isArray(osData.recommendations)) continue;
    const recMap = {};

    osData.recommendations.forEach(rec => {
      const ip = rec.environment?.ip_address;
      if (!ip) return;

      if (!recMap[ip]) {
        recMap[ip] = {
          ...rec,
          patches: {
            low: rec.patches?.low ? [...rec.patches.low] : [],
            medium: rec.patches?.medium ? [...rec.patches.medium] : [],
            high: rec.patches?.high ? [...rec.patches.high] : [],
            critical: rec.patches?.critical ? [...rec.patches.critical] : [],
            applications: rec.patches?.applications ? [...rec.patches.applications] : []
          }
        };
      } else {
        const patches = rec.patches || {};
        Object.keys(recMap[ip].patches).forEach(key => {
          if (patches[key]) {
            recMap[ip].patches[key] = recMap[ip].patches[key].concat(patches[key]);
          }
        });
      }
    });

    osData.recommendations = Object.values(recMap);
  }

  return payload;
}

$payload = mergePatchesForAllOS($payload);

